  // --- Audit Log page (module 5) - labels and static section text
  // fully translated; the dynamically-composed detail sentences (which
  // interleave raw amounts, names, and reasons from real data) stay in
  // English for now, since correctly reordering them per language needs
  // real per-language sentence templates, not word-by-word substitution. ---
  'Audit log': { ar: 'سجل التدقيق', ru: 'Журнал аудита', es: 'Registro de auditoría', hi: 'ऑडिट लॉग', ur: 'آڈٹ لاگ', tl: 'Audit Log', zh: '审计日志', fr: "Journal d'audit" },
  'Every void, refund, staff-placed order, and card deletion — who did it, and when. Not a general activity feed by design.': { ar: 'كل إلغاء، استرداد، طلب وضعه الموظفون، وحذف بطاقة — من فعل ذلك، ومتى. ليس سجل نشاط عام بتصميم مقصود.', ru: 'Каждая отмена, возврат, заказ от персонала и удаление карты - кто и когда это сделал. Не общая лента активности - так задумано.', es: 'Cada anulación, reembolso, pedido tomado por el personal y eliminación de tarjeta — quién lo hizo y cuándo. No es un feed de actividad general, por diseño.', hi: 'हर वॉइड, रिफंड, स्टाफ द्वारा दिया गया ऑर्डर, और कार्ड डिलीशन — किसने किया, और कब। जानबूझकर सामान्य गतिविधि फ़ीड नहीं है।', ur: 'ہر وائیڈ، رقم کی واپسی، عملے کا رکھا گیا آرڈر، اور کارڈ کا حذف — کس نے کیا، اور کب۔ جان بوجھ کر عمومی سرگرمی فیڈ نہیں ہے۔', tl: 'Bawat void, refund, order na inilagay ng staff, at pagtanggal ng card — sino ang gumawa, at kailan. Hindi pangkalahatang activity feed sa disenyo.', zh: '每一次作废、退款、员工下单和卡片删除 — 谁做的，何时做的。这不是一个通用的活动流，是刻意设计的。', fr: "Chaque annulation, remboursement, commande passée par le personnel et suppression de carte — qui l'a fait, et quand. Ce n'est pas un flux d'activité général, par conception." },
  'No activity logged yet.': { ar: 'لا يوجد نشاط مسجّل بعد.', ru: 'Пока нет записанной активности.', es: 'Aún no hay actividad registrada.', hi: 'अभी तक कोई गतिविधि दर्ज नहीं की गई है।', ur: 'ابھی تک کوئی سرگرمی درج نہیں ہوئی۔', tl: 'Wala pang naitalang aktibidad.', zh: '尚无记录的活动。', fr: 'Aucune activité enregistrée pour le moment.' },
  'Deleted item': { ar: 'عنصر محذوف', ru: 'Удалённый товар', es: 'Artículo eliminado', hi: 'हटाई गई वस्तु', ur: 'حذف شدہ چیز', tl: 'Tinanggal na Item', zh: '已删除项目', fr: 'Article supprimé' },
  'Refund issued': { ar: 'تم إصدار استرداد', ru: 'Возврат оформлен', es: 'Reembolso emitido', hi: 'रिफंड जारी किया गया', ur: 'رقم کی واپسی جاری کی گئی', tl: 'Na-issue ang Refund', zh: '已退款', fr: 'Remboursement émis' },
  'Payment recorded': { ar: 'تم تسجيل الدفعة', ru: 'Платёж зафиксирован', es: 'Pago registrado', hi: 'भुगतान दर्ज किया गया', ur: 'ادائیگی درج کی گئی', tl: 'Naitala ang Bayad', zh: '已记录付款', fr: 'Paiement enregistré' },
  'Payment settings changed': { ar: 'تم تغيير إعدادات الدفع', ru: 'Настройки платежей изменены', es: 'Configuración de pago cambiada', hi: 'भुगतान सेटिंग्स बदली गईं', ur: 'ادائیگی کی ترتیبات تبدیل ہوئیں', tl: 'Nabago ang Payment Settings', zh: '付款设置已更改', fr: 'Paramètres de paiement modifiés' },
  'Removed from bill': { ar: 'أُزيل من الفاتورة', ru: 'Удалено из счёта', es: 'Eliminado de la cuenta', hi: 'बिल से हटाया गया', ur: 'بل سے ہٹایا گیا', tl: 'Tinanggal sa Bill', zh: '已从账单移除', fr: "Retiré de l'addition" },
