  'Confirm new password': { ar: 'تأكيد كلمة المرور الجديدة', ru: 'Подтвердите новый пароль', es: 'Confirmar nueva contraseña', hi: 'नए पासवर्ड की पुष्टि करें', ur: 'نئے پاس ورڈ کی تصدیق کریں', tl: 'Kumpirmahin ang Bagong Password', zh: '确认新密码', fr: 'Confirmer le nouveau mot de passe' },
