  'Delivery Platforms': { ar: 'منصات التوصيل', ru: 'Платформы доставки', es: 'Plataformas de entrega', hi: 'डिलीवरी प्लेटफ़ॉर्म', ur: 'ڈیلیوری پلیٹ فارمز', tl: 'Mga Delivery Platform', zh: '外送平台', fr: 'Plateformes de livraison' },
