  'Sync now': { ar: 'مزامنة الآن', ru: 'Синхронизировать сейчас', es: 'Sincronizar ahora', hi: 'अभी सिंक करें', ur: 'ابھی سنک کریں', tl: 'I-sync Ngayon', zh: '立即同步', fr: 'Synchroniser maintenant' },
