  '(contact Tavzio to change)': { ar: '(تواصل مع Tavzio للتغيير)', ru: '(свяжитесь с Tavzio для изменения)', es: '(contacte a Tavzio para cambiar)', hi: '(बदलने के लिए Tavzio से संपर्क करें)', ur: '(تبدیل کرنے کے لیے Tavzio سے رابطہ کریں)', tl: '(makipag-ugnayan sa Tavzio para baguhin)', zh: '（如需更改请联系 Tavzio）', fr: '(contactez Tavzio pour changer)' },
