  '+ Add a service inside': { ar: '+ إضافة خدمة داخل', ru: '+ Добавить услугу внутри', es: '+ Añadir un servicio dentro de', hi: '+ अंदर एक सेवा जोड़ें', ur: '+ اندر ایک سروس شامل کریں', tl: '+ Magdagdag ng serbisyo sa loob ng', zh: '+ 在其中添加服务', fr: '+ Ajouter un service dans' },
  'from the guest portal?': { ar: 'من بوابة الضيوف؟', ru: 'из гостевого портала?', es: 'del portal de huéspedes?', hi: 'गेस्ट पोर्टल से?', ur: 'گیسٹ پورٹل سے؟', tl: 'mula sa guest portal?', zh: '从客人门户中移除吗？', fr: 'du portail client ?' },
