// Falls back to the original English string for anything not yet in the
// dictionary above (or for 'en' itself) - never a blank or a raw key
// leaking through, and safe to call with fresh, still-untranslated text
// as more of the dashboard gets covered module by module.
export function translateNavLabel(text: string, lang: string | undefined): string {
  if (!lang || lang === 'en') return text;
  return DASHBOARD_TRANSLATIONS[text]?.[lang as NavLanguageCode] || text;
}

// Same function, generic name - translateNavLabel kept as an alias so
// nothing that already imports it needs to change.
export const t = translateNavLabel;
